#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    long long key;
    int priority;
    int count;
    int size;
    struct Node *left;
    struct Node *right;
} Node;

#define MAXN 100005

static Node pool[MAXN];
static int pool_ptr = 0;

static inline int get_size(Node *t) {
    return t ? t->size : 0;
}

static inline void update_size(Node *t) {
    if (t) {
        t->size = get_size(t->left) + get_size(t->right) + t->count;
    }
}

static Node* rotate_right(Node *y) {
    Node *x = y->left;
    Node *T2 = x->right;
    x->right = y;
    y->left = T2;
    update_size(y);
    update_size(x);
    return x;
}

static Node* rotate_left(Node *x) {
    Node *y = x->right;
    Node *T2 = y->left;
    y->left = x;
    x->right = T2;
    update_size(x);
    update_size(y);
    return y;
}

static Node* insert(Node *t, long long key) {
    if (!t) {
        Node *n = &pool[pool_ptr++];
        n->key = key;
        n->priority = rand();
        n->count = 1;
        n->size = 1;
        n->left = NULL;
        n->right = NULL;
        return n;
    }

    if (key == t->key) {
        t->count++;
        t->size++;
        return t;
    }

    if (key < t->key) {
        t->left = insert(t->left, key);
        if (t->left->priority > t->priority) {
            t = rotate_right(t);
        }
    } else {
        t->right = insert(t->right, key);
        if (t->right->priority > t->priority) {
            t = rotate_left(t);
        }
    }

    update_size(t);
    return t;
}

static int count_leq(Node *t, long long key) {
    int ans = 0;
    while (t) {
        if (t->key <= key) {
            ans += get_size(t->left) + t->count;
            t = t->right;
        } else {
            t = t->left;
        }
    }
    return ans;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    srand(1337);

    Node *root = NULL;
    long long prev_p = 0;

    for (int i = 0; i < n; i++) {
        long long x, y;
        if (scanf("%lld %lld", &x, &y) != 2) break;

        long long xr = x + prev_p;
        long long yr = y + prev_p;

        long long dist_sq = xr * xr + yr * yr;

        long long p = count_leq(root, dist_sq);
        printf("%lld\n", p);

        root = insert(root, dist_sq);
        prev_p = p;
    }

    return 0;
}
```

